// Normalize the Telegram update. Detect voice notes / audio.
const msg = $input.first().json;
const m = msg.message || {};
const voice = m.voice || m.audio || null;
return [{ json: {
  raw_text: m.text || m.caption || '',
  chat_id: m.chat && m.chat.id,
  username: (m.from && m.from.username) || 'unknown',
  timestamp: new Date().toISOString(),
  is_voice: !!voice,
  voice_file_id: voice ? voice.file_id : null
} }];

// Turn the transcription into the normal message shape.
const r = $input.first().json;
const src = $('Extract message').first().json;
const text = (r && r.text) ? r.text.trim() : '';
return [{ json: { raw_text: text, chat_id: src.chat_id, username: src.username, timestamp: src.timestamp } }];

// Everything goes to Rebeca (assistant-core). Slash commands are mapped to
// natural language so Rebeca picks the right tool; free text is sent as-is.
// Rebeca keeps memory per Telegram chat, so /plan approval works conversationally.
const d = $input.first().json;
let text = (d.raw_text || '').trim();
const MAP = {
  '/task': 'Crea una tarea en Linear: ',
  '/note': 'Guarda una nota en el second brain: ',
  '/plan': 'Planifica esto: propón el plan (proyecto, tarea padre y subtareas) y pídeme confirmación antes de crearlo. ',
  '/calendar': 'Agenda en Google Calendar: ',
  '/cal': 'Agenda en Google Calendar: ',
  '/brain': 'Busca en mi second brain y responde con base en mis notas: ',
  '/show_brain': 'Busca en mi second brain y responde con base en mis notas: ',
  '/web': 'Busca en la web: '
};
const m = text.match(/^(\/[a-z_]+)(?=$|\s)/i);
if (m) {
  const cmd = m[1].toLowerCase();
  const rest = text.slice(m[1].length).trim();
  text = (MAP[cmd] !== undefined) ? (MAP[cmd] + rest) : (rest || text); // /qwen /claude /chat -> plain text
}
if (!text) text = '(mensaje vacío)';
const body = { session_id: 'telegram:' + d.chat_id, message: text, channel: 'telegram' };
return [{ json: { requestBody: JSON.stringify(body), chat_id: d.chat_id } }];

// Rebeca returns { ok, response }. De-markdown lightly so Telegram (parse mode
// None) reads clean, keeping URLs.
const r = $input.first().json;
let text = (r && r.response) ? String(r.response) : '⚠️ Sin respuesta de Rebeca.';
text = text
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/(^|\n)#{1,6}\s*/g, '$1')
  .replace(/`{1,3}/g, '')
  .replace(/^\s*[-*]\s+/gm, '\u2022 ')
  .trim();
if (text.length > 4000) text = text.slice(0, 3990) + '…';
const chat_id = $('To Rebeca').first().json.chat_id;
return [{ json: { text, chat_id } }];
